<template><div class="page-wrap"><div class="page-heading"><span class="eyebrow">GAME LIBRARY</span><h1>发现游戏</h1><p>用筛选和搜索，找到适合你的下一场冒险。</p></div><div class="filter-panel"><input v-model="q" placeholder="搜索名称、介绍或标签…"/><select v-model="category"><option value="">全部分类</option><option v-for="c in data.categories" :key="c.id" :value="c.id">{{ c.name }}</option></select><select v-model="platform"><option value="">全部平台</option><option v-for="p in platforms" :key="p">{{ p }}</option></select><select v-model="tag"><option value="">全部标签</option><option v-for="t in tags" :key="t">{{ t }}</option></select><select v-model="sort"><option value="featured">推荐优先</option><option value="name">名称排序</option><option value="year">年份排序</option></select><button class="text-link" @click="clear">清除筛选</button></div><p class="result-count">找到 {{ filtered.length }} 款游戏</p><div v-if="filtered.length" class="game-grid"><GameCard v-for="g in filtered" :key="g.id" :game="g"/></div><div v-else class="empty-state"><span>⌕</span><h2>没有找到匹配的游戏</h2><p>试试其他关键词，或清除筛选条件。</p><button class="button primary" @click="clear">清除筛选</button></div></div></template>
<script setup>
import { inject, computed, ref } from 'vue'; import { useRoute } from 'vue-router'; import GameCard from '../components/GameCard.vue'
const data=inject('siteData'), route=useRoute(), q=ref(String(route.query.q||'')), category=ref(String(route.query.category||'')), platform=ref(''), tag=ref(''), sort=ref('featured'), games=computed(()=>data.games.filter(g=>g.published)), platforms=computed(()=>[...new Set(games.value.flatMap(g=>g.platforms||[]))]), tags=computed(()=>[...new Set(games.value.flatMap(g=>g.tags||[]))])
const filtered=computed(()=>{let list=games.value.filter(g=>{const cat=data.categories.filter(c=>g.categoryIds?.includes(c.id)).map(c=>c.name).join(' '); const hay=[g.title,g.subtitle,g.description,cat,...(g.tags||[])].join(' ').toLowerCase(); return (!q.value||hay.includes(q.value.toLowerCase()))&&(!category.value||g.categoryIds?.includes(category.value))&&(!platform.value||g.platforms?.includes(platform.value))&&(!tag.value||g.tags?.includes(tag.value))}); return list.sort((a,b)=>sort.value==='name'?a.title.localeCompare(b.title,'zh'):sort.value==='year'?(b.releaseYear||0)-(a.releaseYear||0):Number(b.recommended)-Number(a.recommended))})
function clear(){q.value='';category.value='';platform.value='';tag.value='';sort.value='featured'}
</script>
